draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // dog body
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2*Math.PI);
  ctx.fill();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fill();

  // ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 15, H/2 - 70);
  ctx.lineTo(W/2 - 30, H/2 - 90);
  ctx.lineTo(W/2 - 15, H/2 - 110);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 15, H/2 - 70);
  ctx.lineTo(W/2 + 30, H/2 - 90);
  ctx.lineTo(W/2 + 15, H/2 - 110);
  ctx.stroke();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 5, H/2 - 55, 5, 0, 2*Math.PI);
  ctx.fill();

  ctx.beginPath();
  ctx.arc(W/2 + 5, H/2 - 55, 5, 0, 2*Math.PI);
  ctx.fill();

  // guilty expression
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 60, 10, 0, Math.PI);
  ctx.stroke();

  // paws
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 20);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 20);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
